window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-0acd62c6383ca86f"]={"versions": [{"id": "FIG-0acd62c6383ca86f", "releases": ["R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> Komponenten- und Deployment-Diagramm für serviceorientierte Architekturen (SOA) gemäß AUTOSAR Adaptive Platform (AP) Modellierungskonventionen.</li>\n<li><strong>Kontext:</strong> AUTOSAR AP Release R21-11, Spezifikation <code>AUTOSAR_TPS_ManifestSpecification</code>, Kapitel zu <em>Service Interface Deployment</em> und <code>ServiceInterfaceElementMapping</code>.</li>\n<li><strong>Technischer Zweck:</strong> Veranschaulichung des Facade-Entwurfsmusters zur Aggregation und Aufteilung (Splitting/Decomposition) von Service-Elementen (<code>Event</code>, <code>Method</code>) zwischen maschinen-lokalen ServiceInterfaces und einer netzwerkweiten SOME/IP-Service-Instanz. Es zeigt das Selektieren von Teilmengen (Subsets) auf Provider-Seite sowie die bedarfsgerechte Rekombination auf Consumer-Seite über Maschinengrenzen hinweg.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Entitäten & Deployment-Knoten</p>\n<ul class=\"fig-list\">\n<li><strong>Machine 1 (Provider-Knoten):</strong></li>\n<li><code>AppM1_1</code> (Adaptive Application): Provider für <code>Service 1</code> über einen Provided Port (<code>P</code>).</li>\n<li><code>AppM1_2</code> (Adaptive Application): Provider für <code>Service 2</code> über einen Provided Port (<code>P</code>).</li>\n<li><code>AppM2_3</code> (Lokale Consumer-Applikation auf Machine 1): Konsumiert <code>Service 2</code> intern über Required Port (<code>R</code>).</li>\n<li><code>Facade</code> (Adaptive Application / Service Broker):</li>\n<li>2× Required Ports (<code>R</code>): Terminierung der lokalen Schnittstellen von <code>AppM1_1</code> und <code>AppM1_2</code>.</li>\n<li>1× Provided Port (<code>P</code>): Aggregierte SOME/IP-Schnittstelle zur Machine 2.</li>\n<li><strong>Machine 2 (Consumer-Knoten):</strong></li>\n<li><code>Facade</code> (Adaptive Application / Service Dispatcher):</li>\n<li>1× Required Port (<code>R</code>): Empfang der SOME/IP-Service-Instanz über das Netzwerk.</li>\n<li>2× Provided Ports (<code>P</code>): Bereitstellung der aufgeteilten Subsets an die lokalen Konsumenten.</li>\n<li><code>AppM2_1</code> (Adaptive Application): Consumer für <code>Service 3</code> über Required Port (<code>R</code>).</li>\n<li><code>AppM2_2</code> (Adaptive Application): Consumer für <code>Service 4</code> über Required Port (<code>R</code>).</li>\n</ul>\n<p class=\"fig-p\">#### Schnittstellen, Element-Granularität & Mapping</p>\n<ul class=\"fig-list\">\n<li><strong><code>Service 1</code> (Machine 1 intern):</strong> Besteht aus <code>{Event1, Event2, Method1}</code>.</li>\n<li><strong><code>Service 2</code> (Machine 1 intern):</strong> Besteht aus <code>{Event3, Event4, Method2}</code>.</li>\n<li><strong><code>SOME/IP Service</code> (Netzwerk-Ebene):</strong> Aggregiert selektiv <code>{Event1, Event2, Event3, Method1}</code>.</li>\n<li><em>Subset-Extraktion Provider-Seite:</em> Vollständige Übernahme von <code>Service 1</code>; selektive Extraktion von <code>Event3</code> aus <code>Service 2</code>. Die Elemente <code>Event4</code> und <code>Method2</code> verbleiben lokal bei <code>AppM2_3</code> und belasten das Netzwerk nicht.</li>\n<li><strong><code>Service 3</code> (Machine 2 intern):</strong> Rekombiniertes Subset bestehend aus <code>{Event1, Event3, Method1}</code> für <code>AppM2_1</code>.</li>\n<li><strong><code>Service 4</code> (Machine 2 intern):</strong> Isoliertes Subset bestehend aus <code>{Event2}</code> für <code>AppM2_2</code>.</li>\n</ul>\n<p class=\"fig-p\">#### Port-Kardinalitäten & Topologie</p>\n<ul class=\"fig-list\">\n<li><strong>1:n-Fächerung:</strong> <code>AppM1_2</code> (Port <code>P</code>) bedient simultan die lokale Instanz <code>AppM2_3</code> (Port <code>R</code>) sowie die <code>Facade</code> (Port <code>R</code>).</li>\n<li><strong>N:1-Aggregation:</strong> Machine 1 <code>Facade</code> bündelt zwei R-Ports auf einen netzwerkweiten P-Port.</li>\n<li><strong>1:N-Segregation:</strong> Machine 2 <code>Facade</code> teilt einen netzwerkweiten R-Port auf zwei lokale P-Ports auf.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">#### Event-Propagation (Asynchroner Pfad)</p>\n<ol class=\"fig-list\">\n<li><strong>Trigger:</strong> <code>AppM1_1</code> emittiert <code>Event1</code>/<code>Event2</code>; <code>AppM1_2</code> emittiert <code>Event3</code> (via <code>ara::com</code> Skeleton-Methoden <code>Send()</code>).</li>\n<li><strong>Lokale Zustellung Machine 1:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Daten passieren den lokalen IPC-Pfad (z. B. Shared Memory / Unix Domain Sockets) zu den R-Ports der providerseitigen <code>Facade</code>.</li>\n<li><code>AppM2_3</code> empfängt parallel <code>Event3</code> und <code>Event4</code> direkt über lokalen IPC.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Netzwerk-Serialisierung:</strong> Die <code>Facade</code> auf Machine 1 triggert die SOME/IP-Serialisierung der gemeinsamen Service-Instanz und sendet SOME/IP-Events via UDP/TCP über das Fahrzeug-Ethernet.</li>\n<li><strong>Empfang & Demultiplexing Machine 2:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Der SOME/IP-Daemon / Netzwerk-Stack von Machine 2 routet das Paket an den R-Port der Consumer-<code>Facade</code>.</li>\n<li>Die <code>Facade</code> trennt die Payload anhand des konfigurierten Mappings:</li>\n<li><code>Event1</code> und <code>Event3</code> werden auf <code>Service 3</code> gemappt und via lokalem IPC an <code>AppM2_1</code> gesendet.</li>\n<li><code>Event2</code> wird auf <code>Service 4</code> gemappt und via lokalem IPC an <code>AppM2_2</code> zugestellt.</li>\n</ul>\n<p class=\"fig-p\">#### Methoden-Aufruf (Synchroner / Asynchroner Request-Response-Pfad)</p>\n<ol class=\"fig-list\">\n<li><code>AppM2_1</code> ruft <code>Method1</code> auf dem Proxy von <code>Service 3</code> auf.</li>\n<li>Der Aufruf wird über lokalen IPC zur <code>Facade</code> (Machine 2) übertragen.</li>\n<li>Die <code>Facade</code> auf Machine 2 kapselt den Methodenaufruf in eine SOME/IP-Request-Message (<code>SOME/IP Service</code>).</li>\n<li>Machine 1 empfängt die Request-Message am P-Port der <code>Facade</code>, leitet sie per IPC an den R-Port und weiter an das Skeleton von <code>AppM1_1</code>.</li>\n<li>Die Antwort (<code>Response</code>) durchläuft denselben Pfad invers zurück zu <code>AppM2_1</code> (Auflösung des <code>ara::core::Future</code>).</li>\n</ol>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Manifest-Modellierung (<code>ExecutionManifest</code> & <code>ServiceInstanceManifest</code>):</strong></li>\n<li>Werden Service-Schnittstellen nicht 1:1 netzwerkweit exponiert, erfordert AUTOSAR AP entweder ein direktes <code>ServiceInterfaceElementMapping</code> innerhalb des Deployment-Modells oder den im Diagramm gezeigten Architektur-Workaround mittels expliziter Facade-SWCs.</li>\n<li>Das Mapping verlangt konsistente Datentypen (<code>ApplicationDataType</code> / <code>ImplementationDataType</code>) zwischen den Quell-Elementen von <code>Service 1</code>/<code>Service 2</code> und den Ziel-Elementen von <code>Service 3</code>/<code>Service 4</code>.</li>\n<li><strong>Einfluss auf API-Vertrag (<code>ara::com</code>):</strong></li>\n<li>Die Applikationen (<code>AppM1_x</code>, <code>AppM2_x</code>) bleiben strikt vom physischen SOME/IP-Deployment entkoppelt. Sie implementieren bzw. instanziieren Standard-<code>Proxy</code>- und <code>Skeleton</code>-Klassen ihrer jeweiligen ServiceInterfaces (<code>Service 1</code> bis <code>Service 4</code>).</li>\n<li>Die Facade-Komponenten müssen sowohl Skeleton- als auch Proxy-Instanzen halten und den Datentransfer zwischen ihren R- und P-Ports manuell oder teilgeneriert durchschleifen.</li>\n<li><strong>Performance-, Latenz- und Determinismus-Implikationen:</strong></li>\n<li><strong>Doppelter IPC-Hop:</strong> Aufrufe und Events passieren zwei zusätzliche Prozessgrenzen (Applikation $\\rightarrow$ Facade $\\rightarrow$ Netzwerk-Stack $\\rightarrow$ Netzwerk $\\rightarrow$ Netzwerk-Stack $\\rightarrow$ Facade $\\rightarrow$ Applikation).</li>\n<li><strong>Latenzanalyse:</strong> Bei synchronen Methodenaufrufen (<code>Method1</code>) addieren sich Kontextwechsel und Pufferkopien der IPC-Mechanismen auf beiden Knoten zur Netzwerk-Roundtrip-Time (RTT). Timeout-Parameter für <code>ara::core::Future::wait_for()</code> müssen entsprechend dimensioniert werden.</li>\n<li><strong>Bandbreiten-Optimierung:</strong> Das gezielte Ausblenden irrelevanter Elemente (<code>Event4</code>, <code>Method2</code>) verhindert unnötigen SOME/IP-Traffic und entlastet das Ethernet-Bordnetzwerk.</li>\n</ul>"}, {"id": "FIG-f4c7afdd5f68e0f8", "releases": ["R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> Komponenten- und Deployment-Diagramm für serviceorientierte Architekturen (SOA) gemäß AUTOSAR Adaptive Platform (AP) Modellierungskonventionen.</li>\n<li><strong>Kontext:</strong> AUTOSAR AP Release R21-11, Spezifikation <code>AUTOSAR_TPS_ManifestSpecification</code>, Kapitel zu <em>Service Interface Deployment</em> und <code>ServiceInterfaceElementMapping</code>.</li>\n<li><strong>Technischer Zweck:</strong> Veranschaulichung des Facade-Entwurfsmusters zur Aggregation und Aufteilung (Splitting/Decomposition) von Service-Elementen (<code>Event</code>, <code>Method</code>) zwischen maschinen-lokalen ServiceInterfaces und einer netzwerkweiten SOME/IP-Service-Instanz. Es zeigt das Selektieren von Teilmengen (Subsets) auf Provider-Seite sowie die bedarfsgerechte Rekombination auf Consumer-Seite über Maschinengrenzen hinweg.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Entitäten & Deployment-Knoten</p>\n<ul class=\"fig-list\">\n<li><strong>Machine 1 (Provider-Knoten):</strong></li>\n<li><code>AppM1_1</code> (Adaptive Application): Provider für <code>Service 1</code> über einen Provided Port (<code>P</code>).</li>\n<li><code>AppM1_2</code> (Adaptive Application): Provider für <code>Service 2</code> über einen Provided Port (<code>P</code>).</li>\n<li><code>AppM2_3</code> (Lokale Consumer-Applikation auf Machine 1): Konsumiert <code>Service 2</code> intern über Required Port (<code>R</code>).</li>\n<li><code>Facade</code> (Adaptive Application / Service Broker):</li>\n<li>2× Required Ports (<code>R</code>): Terminierung der lokalen Schnittstellen von <code>AppM1_1</code> und <code>AppM1_2</code>.</li>\n<li>1× Provided Port (<code>P</code>): Aggregierte SOME/IP-Schnittstelle zur Machine 2.</li>\n<li><strong>Machine 2 (Consumer-Knoten):</strong></li>\n<li><code>Facade</code> (Adaptive Application / Service Dispatcher):</li>\n<li>1× Required Port (<code>R</code>): Empfang der SOME/IP-Service-Instanz über das Netzwerk.</li>\n<li>2× Provided Ports (<code>P</code>): Bereitstellung der aufgeteilten Subsets an die lokalen Konsumenten.</li>\n<li><code>AppM2_1</code> (Adaptive Application): Consumer für <code>Service 3</code> über Required Port (<code>R</code>).</li>\n<li><code>AppM2_2</code> (Adaptive Application): Consumer für <code>Service 4</code> über Required Port (<code>R</code>).</li>\n</ul>\n<p class=\"fig-p\">#### Schnittstellen, Element-Granularität & Mapping</p>\n<ul class=\"fig-list\">\n<li><strong><code>Service 1</code> (Machine 1 intern):</strong> Besteht aus <code>{Event1, Event2, Method1}</code>.</li>\n<li><strong><code>Service 2</code> (Machine 1 intern):</strong> Besteht aus <code>{Event3, Event4, Method2}</code>.</li>\n<li><strong><code>SOME/IP Service</code> (Netzwerk-Ebene):</strong> Aggregiert selektiv <code>{Event1, Event2, Event3, Method1}</code>.</li>\n<li><em>Subset-Extraktion Provider-Seite:</em> Vollständige Übernahme von <code>Service 1</code>; selektive Extraktion von <code>Event3</code> aus <code>Service 2</code>. Die Elemente <code>Event4</code> und <code>Method2</code> verbleiben lokal bei <code>AppM2_3</code> und belasten das Netzwerk nicht.</li>\n<li><strong><code>Service 3</code> (Machine 2 intern):</strong> Rekombiniertes Subset bestehend aus <code>{Event1, Event3, Method1}</code> für <code>AppM2_1</code>.</li>\n<li><strong><code>Service 4</code> (Machine 2 intern):</strong> Isoliertes Subset bestehend aus <code>{Event2}</code> für <code>AppM2_2</code>.</li>\n</ul>\n<p class=\"fig-p\">#### Port-Kardinalitäten & Topologie</p>\n<ul class=\"fig-list\">\n<li><strong>1:n-Fächerung:</strong> <code>AppM1_2</code> (Port <code>P</code>) bedient simultan die lokale Instanz <code>AppM2_3</code> (Port <code>R</code>) sowie die <code>Facade</code> (Port <code>R</code>).</li>\n<li><strong>N:1-Aggregation:</strong> Machine 1 <code>Facade</code> bündelt zwei R-Ports auf einen netzwerkweiten P-Port.</li>\n<li><strong>1:N-Segregation:</strong> Machine 2 <code>Facade</code> teilt einen netzwerkweiten R-Port auf zwei lokale P-Ports auf.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">#### Event-Propagation (Asynchroner Pfad)</p>\n<ol class=\"fig-list\">\n<li><strong>Trigger:</strong> <code>AppM1_1</code> emittiert <code>Event1</code>/<code>Event2</code>; <code>AppM1_2</code> emittiert <code>Event3</code> (via <code>ara::com</code> Skeleton-Methoden <code>Send()</code>).</li>\n<li><strong>Lokale Zustellung Machine 1:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Daten passieren den lokalen IPC-Pfad (z. B. Shared Memory / Unix Domain Sockets) zu den R-Ports der providerseitigen <code>Facade</code>.</li>\n<li><code>AppM2_3</code> empfängt parallel <code>Event3</code> und <code>Event4</code> direkt über lokalen IPC.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Netzwerk-Serialisierung:</strong> Die <code>Facade</code> auf Machine 1 triggert die SOME/IP-Serialisierung der gemeinsamen Service-Instanz und sendet SOME/IP-Events via UDP/TCP über das Fahrzeug-Ethernet.</li>\n<li><strong>Empfang & Demultiplexing Machine 2:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Der SOME/IP-Daemon / Netzwerk-Stack von Machine 2 routet das Paket an den R-Port der Consumer-<code>Facade</code>.</li>\n<li>Die <code>Facade</code> trennt die Payload anhand des konfigurierten Mappings:</li>\n<li><code>Event1</code> und <code>Event3</code> werden auf <code>Service 3</code> gemappt und via lokalem IPC an <code>AppM2_1</code> gesendet.</li>\n<li><code>Event2</code> wird auf <code>Service 4</code> gemappt und via lokalem IPC an <code>AppM2_2</code> zugestellt.</li>\n</ul>\n<p class=\"fig-p\">#### Methoden-Aufruf (Synchroner / Asynchroner Request-Response-Pfad)</p>\n<ol class=\"fig-list\">\n<li><code>AppM2_1</code> ruft <code>Method1</code> auf dem Proxy von <code>Service 3</code> auf.</li>\n<li>Der Aufruf wird über lokalen IPC zur <code>Facade</code> (Machine 2) übertragen.</li>\n<li>Die <code>Facade</code> auf Machine 2 kapselt den Methodenaufruf in eine SOME/IP-Request-Message (<code>SOME/IP Service</code>).</li>\n<li>Machine 1 empfängt die Request-Message am P-Port der <code>Facade</code>, leitet sie per IPC an den R-Port und weiter an das Skeleton von <code>AppM1_1</code>.</li>\n<li>Die Antwort (<code>Response</code>) durchläuft denselben Pfad invers zurück zu <code>AppM2_1</code> (Auflösung des <code>ara::core::Future</code>).</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Manifest-Modellierung (<code>ExecutionManifest</code> & <code>ServiceInstanceManifest</code>):</strong></li>\n<li>Werden Service-Schnittstellen nicht 1:1 netzwerkweit exponiert, erfordert AUTOSAR AP entweder ein direktes <code>ServiceInterfaceElementMapping</code> innerhalb des Deployment-Modells oder den im Diagramm gezeigten Architektur-Workaround mittels expliziter Facade-SWCs.</li>\n<li>Das Mapping verlangt konsistente Datentypen (<code>ApplicationDataType</code> / <code>ImplementationDataType</code>) zwischen den Quell-Elementen von <code>Service 1</code>/<code>Service 2</code> und den Ziel-Elementen von <code>Service 3</code>/<code>Service 4</code>.</li>\n<li><strong>Einfluss auf API-Vertrag (<code>ara::com</code>):</strong></li>\n<li>Die Applikationen (<code>AppM1_x</code>, <code>AppM2_x</code>) bleiben strikt vom physischen SOME/IP-Deployment entkoppelt. Sie implementieren bzw. instanziieren Standard-<code>Proxy</code>- und <code>Skeleton</code>-Klassen ihrer jeweiligen ServiceInterfaces (<code>Service 1</code> bis <code>Service 4</code>).</li>\n<li>Die Facade-Komponenten müssen sowohl Skeleton- als auch Proxy-Instanzen halten und den Datentransfer zwischen ihren R- und P-Ports manuell oder teilgeneriert durchschleifen.</li>\n<li><strong>Performance-, Latenz- und Determinismus-Implikationen:</strong></li>\n<li><strong>Doppelter IPC-Hop:</strong> Aufrufe und Events passieren zwei zusätzliche Prozessgrenzen (Applikation $\\rightarrow$ Facade $\\rightarrow$ Netzwerk-Stack $\\rightarrow$ Netzwerk $\\rightarrow$ Netzwerk-Stack $\\rightarrow$ Facade $\\rightarrow$ Applikation).</li>\n<li><strong>Latenzanalyse:</strong> Bei synchronen Methodenaufrufen (<code>Method1</code>) addieren sich Kontextwechsel und Pufferkopien der IPC-Mechanismen auf beiden Knoten zur Netzwerk-Roundtrip-Time (RTT). Timeout-Parameter für <code>ara::core::Future::wait_for()</code> müssen entsprechend dimensioniert werden.</li>\n<li><strong>Bandbreiten-Optimierung:</strong> Das gezielte Ausblenden irrelevanter Elemente (<code>Event4</code>, <code>Method2</code>) verhindert unnötigen SOME/IP-Traffic und entlastet das Ethernet-Bordnetzwerk.</li>\n</ul>"}, {"id": "FIG-b8956c717dfea76b", "releases": ["R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> Komponenten- und Deployment-Diagramm für serviceorientierte Architekturen (SOA) gemäß AUTOSAR Adaptive Platform (AP) Modellierungskonventionen.</li>\n<li><strong>Kontext:</strong> AUTOSAR AP Release R21-11, Spezifikation <code>AUTOSAR_TPS_ManifestSpecification</code>, Kapitel zu <em>Service Interface Deployment</em> und <code>ServiceInterfaceElementMapping</code>.</li>\n<li><strong>Technischer Zweck:</strong> Veranschaulichung des Facade-Entwurfsmusters zur Aggregation und Aufteilung (Splitting/Decomposition) von Service-Elementen (<code>Event</code>, <code>Method</code>) zwischen maschinen-lokalen ServiceInterfaces und einer netzwerkweiten SOME/IP-Service-Instanz. Es zeigt das Selektieren von Teilmengen (Subsets) auf Provider-Seite sowie die bedarfsgerechte Rekombination auf Consumer-Seite über Maschinengrenzen hinweg.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Entitäten & Deployment-Knoten</p>\n<ul class=\"fig-list\">\n<li><strong>Machine 1 (Provider-Knoten):</strong></li>\n<li><code>AppM1_1</code> (Adaptive Application): Provider für <code>Service 1</code> über einen Provided Port (<code>P</code>).</li>\n<li><code>AppM1_2</code> (Adaptive Application): Provider für <code>Service 2</code> über einen Provided Port (<code>P</code>).</li>\n<li><code>AppM2_3</code> (Lokale Consumer-Applikation auf Machine 1): Konsumiert <code>Service 2</code> intern über Required Port (<code>R</code>).</li>\n<li><code>Facade</code> (Adaptive Application / Service Broker):</li>\n<li>2× Required Ports (<code>R</code>): Terminierung der lokalen Schnittstellen von <code>AppM1_1</code> und <code>AppM1_2</code>.</li>\n<li>1× Provided Port (<code>P</code>): Aggregierte SOME/IP-Schnittstelle zur Machine 2.</li>\n<li><strong>Machine 2 (Consumer-Knoten):</strong></li>\n<li><code>Facade</code> (Adaptive Application / Service Dispatcher):</li>\n<li>1× Required Port (<code>R</code>): Empfang der SOME/IP-Service-Instanz über das Netzwerk.</li>\n<li>2× Provided Ports (<code>P</code>): Bereitstellung der aufgeteilten Subsets an die lokalen Konsumenten.</li>\n<li><code>AppM2_1</code> (Adaptive Application): Consumer für <code>Service 3</code> über Required Port (<code>R</code>).</li>\n<li><code>AppM2_2</code> (Adaptive Application): Consumer für <code>Service 4</code> über Required Port (<code>R</code>).</li>\n</ul>\n<p class=\"fig-p\">#### Schnittstellen, Element-Granularität & Mapping</p>\n<ul class=\"fig-list\">\n<li><strong><code>Service 1</code> (Machine 1 intern):</strong> Besteht aus <code>{Event1, Event2, Method1}</code>.</li>\n<li><strong><code>Service 2</code> (Machine 1 intern):</strong> Besteht aus <code>{Event3, Event4, Method2}</code>.</li>\n<li><strong><code>SOME/IP Service</code> (Netzwerk-Ebene):</strong> Aggregiert selektiv <code>{Event1, Event2, Event3, Method1}</code>.</li>\n<li><em>Subset-Extraktion Provider-Seite:</em> Vollständige Übernahme von <code>Service 1</code>; selektive Extraktion von <code>Event3</code> aus <code>Service 2</code>. Die Elemente <code>Event4</code> und <code>Method2</code> verbleiben lokal bei <code>AppM2_3</code> und belasten das Netzwerk nicht.</li>\n<li><strong><code>Service 3</code> (Machine 2 intern):</strong> Rekombiniertes Subset bestehend aus <code>{Event1, Event3, Method1}</code> für <code>AppM2_1</code>.</li>\n<li><strong><code>Service 4</code> (Machine 2 intern):</strong> Isoliertes Subset bestehend aus <code>{Event2}</code> für <code>AppM2_2</code>.</li>\n</ul>\n<p class=\"fig-p\">#### Port-Kardinalitäten & Topologie</p>\n<ul class=\"fig-list\">\n<li><strong>1:n-Fächerung:</strong> <code>AppM1_2</code> (Port <code>P</code>) bedient simultan die lokale Instanz <code>AppM2_3</code> (Port <code>R</code>) sowie die <code>Facade</code> (Port <code>R</code>).</li>\n<li><strong>N:1-Aggregation:</strong> Machine 1 <code>Facade</code> bündelt zwei R-Ports auf einen netzwerkweiten P-Port.</li>\n<li><strong>1:N-Segregation:</strong> Machine 2 <code>Facade</code> teilt einen netzwerkweiten R-Port auf zwei lokale P-Ports auf.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">#### Event-Propagation (Asynchroner Pfad)</p>\n<ol class=\"fig-list\">\n<li><strong>Trigger:</strong> <code>AppM1_1</code> emittiert <code>Event1</code>/<code>Event2</code>; <code>AppM1_2</code> emittiert <code>Event3</code> (via <code>ara::com</code> Skeleton-Methoden <code>Send()</code>).</li>\n<li><strong>Lokale Zustellung Machine 1:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Daten passieren den lokalen IPC-Pfad (z. B. Shared Memory / Unix Domain Sockets) zu den R-Ports der providerseitigen <code>Facade</code>.</li>\n<li><code>AppM2_3</code> empfängt parallel <code>Event3</code> und <code>Event4</code> direkt über lokalen IPC.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Netzwerk-Serialisierung:</strong> Die <code>Facade</code> auf Machine 1 triggert die SOME/IP-Serialisierung der gemeinsamen Service-Instanz und sendet SOME/IP-Events via UDP/TCP über das Fahrzeug-Ethernet.</li>\n<li><strong>Empfang & Demultiplexing Machine 2:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Der SOME/IP-Daemon / Netzwerk-Stack von Machine 2 routet das Paket an den R-Port der Consumer-<code>Facade</code>.</li>\n<li>Die <code>Facade</code> trennt die Payload anhand des konfigurierten Mappings:</li>\n<li><code>Event1</code> und <code>Event3</code> werden auf <code>Service 3</code> gemappt und via lokalem IPC an <code>AppM2_1</code> gesendet.</li>\n<li><code>Event2</code> wird auf <code>Service 4</code> gemappt und via lokalem IPC an <code>AppM2_2</code> zugestellt.</li>\n</ul>\n<p class=\"fig-p\">#### Methoden-Aufruf (Synchroner / Asynchroner Request-Response-Pfad)</p>\n<ol class=\"fig-list\">\n<li><code>AppM2_1</code> ruft <code>Method1</code> auf dem Proxy von <code>Service 3</code> auf.</li>\n<li>Der Aufruf wird über lokalen IPC zur <code>Facade</code> (Machine 2) übertragen.</li>\n<li>Die <code>Facade</code> auf Machine 2 kapselt den Methodenaufruf in eine SOME/IP-Request-Message (<code>SOME/IP Service</code>).</li>\n<li>Machine 1 empfängt die Request-Message am P-Port der <code>Facade</code>, leitet sie per IPC an den R-Port und weiter an das Skeleton von <code>AppM1_1</code>.</li>\n<li>Die Antwort (<code>Response</code>) durchläuft denselben Pfad invers zurück zu <code>AppM2_1</code> (Auflösung des <code>ara::core::Future</code>).</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Manifest-Modellierung (<code>ExecutionManifest</code> & <code>ServiceInstanceManifest</code>):</strong></li>\n<li>Werden Service-Schnittstellen nicht 1:1 netzwerkweit exponiert, erfordert AUTOSAR AP entweder ein direktes <code>ServiceInterfaceElementMapping</code> innerhalb des Deployment-Modells oder den im Diagramm gezeigten Architektur-Workaround mittels expliziter Facade-SWCs.</li>\n<li>Das Mapping verlangt konsistente Datentypen (<code>ApplicationDataType</code> / <code>ImplementationDataType</code>) zwischen den Quell-Elementen von <code>Service 1</code>/<code>Service 2</code> und den Ziel-Elementen von <code>Service 3</code>/<code>Service 4</code>.</li>\n<li><strong>Einfluss auf API-Vertrag (<code>ara::com</code>):</strong></li>\n<li>Die Applikationen (<code>AppM1_x</code>, <code>AppM2_x</code>) bleiben strikt vom physischen SOME/IP-Deployment entkoppelt. Sie implementieren bzw. instanziieren Standard-<code>Proxy</code>- und <code>Skeleton</code>-Klassen ihrer jeweiligen ServiceInterfaces (<code>Service 1</code> bis <code>Service 4</code>).</li>\n<li>Die Facade-Komponenten müssen sowohl Skeleton- als auch Proxy-Instanzen halten und den Datentransfer zwischen ihren R- und P-Ports manuell oder teilgeneriert durchschleifen.</li>\n<li><strong>Performance-, Latenz- und Determinismus-Implikationen:</strong></li>\n<li><strong>Doppelter IPC-Hop:</strong> Aufrufe und Events passieren zwei zusätzliche Prozessgrenzen (Applikation $\\rightarrow$ Facade $\\rightarrow$ Netzwerk-Stack $\\rightarrow$ Netzwerk $\\rightarrow$ Netzwerk-Stack $\\rightarrow$ Facade $\\rightarrow$ Applikation).</li>\n<li><strong>Latenzanalyse:</strong> Bei synchronen Methodenaufrufen (<code>Method1</code>) addieren sich Kontextwechsel und Pufferkopien der IPC-Mechanismen auf beiden Knoten zur Netzwerk-Roundtrip-Time (RTT). Timeout-Parameter für <code>ara::core::Future::wait_for()</code> müssen entsprechend dimensioniert werden.</li>\n<li><strong>Bandbreiten-Optimierung:</strong> Das gezielte Ausblenden irrelevanter Elemente (<code>Event4</code>, <code>Method2</code>) verhindert unnötigen SOME/IP-Traffic und entlastet das Ethernet-Bordnetzwerk.</li>\n</ul>"}, {"id": "FIG-b54dc1f1dcd5453e", "releases": ["R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> Komponenten- und Deployment-Diagramm für serviceorientierte Architekturen (SOA) gemäß AUTOSAR Adaptive Platform (AP) Modellierungskonventionen.</li>\n<li><strong>Kontext:</strong> AUTOSAR AP Release R21-11, Spezifikation <code>AUTOSAR_TPS_ManifestSpecification</code>, Kapitel zu <em>Service Interface Deployment</em> und <code>ServiceInterfaceElementMapping</code>.</li>\n<li><strong>Technischer Zweck:</strong> Veranschaulichung des Facade-Entwurfsmusters zur Aggregation und Aufteilung (Splitting/Decomposition) von Service-Elementen (<code>Event</code>, <code>Method</code>) zwischen maschinen-lokalen ServiceInterfaces und einer netzwerkweiten SOME/IP-Service-Instanz. Es zeigt das Selektieren von Teilmengen (Subsets) auf Provider-Seite sowie die bedarfsgerechte Rekombination auf Consumer-Seite über Maschinengrenzen hinweg.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Entitäten & Deployment-Knoten</p>\n<ul class=\"fig-list\">\n<li><strong>Machine 1 (Provider-Knoten):</strong></li>\n<li><code>AppM1_1</code> (Adaptive Application): Provider für <code>Service 1</code> über einen Provided Port (<code>P</code>).</li>\n<li><code>AppM1_2</code> (Adaptive Application): Provider für <code>Service 2</code> über einen Provided Port (<code>P</code>).</li>\n<li><code>AppM2_3</code> (Lokale Consumer-Applikation auf Machine 1): Konsumiert <code>Service 2</code> intern über Required Port (<code>R</code>).</li>\n<li><code>Facade</code> (Adaptive Application / Service Broker):</li>\n<li>2× Required Ports (<code>R</code>): Terminierung der lokalen Schnittstellen von <code>AppM1_1</code> und <code>AppM1_2</code>.</li>\n<li>1× Provided Port (<code>P</code>): Aggregierte SOME/IP-Schnittstelle zur Machine 2.</li>\n<li><strong>Machine 2 (Consumer-Knoten):</strong></li>\n<li><code>Facade</code> (Adaptive Application / Service Dispatcher):</li>\n<li>1× Required Port (<code>R</code>): Empfang der SOME/IP-Service-Instanz über das Netzwerk.</li>\n<li>2× Provided Ports (<code>P</code>): Bereitstellung der aufgeteilten Subsets an die lokalen Konsumenten.</li>\n<li><code>AppM2_1</code> (Adaptive Application): Consumer für <code>Service 3</code> über Required Port (<code>R</code>).</li>\n<li><code>AppM2_2</code> (Adaptive Application): Consumer für <code>Service 4</code> über Required Port (<code>R</code>).</li>\n</ul>\n<p class=\"fig-p\">#### Schnittstellen, Element-Granularität & Mapping</p>\n<ul class=\"fig-list\">\n<li><strong><code>Service 1</code> (Machine 1 intern):</strong> Besteht aus <code>{Event1, Event2, Method1}</code>.</li>\n<li><strong><code>Service 2</code> (Machine 1 intern):</strong> Besteht aus <code>{Event3, Event4, Method2}</code>.</li>\n<li><strong><code>SOME/IP Service</code> (Netzwerk-Ebene):</strong> Aggregiert selektiv <code>{Event1, Event2, Event3, Method1}</code>.</li>\n<li><em>Subset-Extraktion Provider-Seite:</em> Vollständige Übernahme von <code>Service 1</code>; selektive Extraktion von <code>Event3</code> aus <code>Service 2</code>. Die Elemente <code>Event4</code> und <code>Method2</code> verbleiben lokal bei <code>AppM2_3</code> und belasten das Netzwerk nicht.</li>\n<li><strong><code>Service 3</code> (Machine 2 intern):</strong> Rekombiniertes Subset bestehend aus <code>{Event1, Event3, Method1}</code> für <code>AppM2_1</code>.</li>\n<li><strong><code>Service 4</code> (Machine 2 intern):</strong> Isoliertes Subset bestehend aus <code>{Event2}</code> für <code>AppM2_2</code>.</li>\n</ul>\n<p class=\"fig-p\">#### Port-Kardinalitäten & Topologie</p>\n<ul class=\"fig-list\">\n<li><strong>1:n-Fächerung:</strong> <code>AppM1_2</code> (Port <code>P</code>) bedient simultan die lokale Instanz <code>AppM2_3</code> (Port <code>R</code>) sowie die <code>Facade</code> (Port <code>R</code>).</li>\n<li><strong>N:1-Aggregation:</strong> Machine 1 <code>Facade</code> bündelt zwei R-Ports auf einen netzwerkweiten P-Port.</li>\n<li><strong>1:N-Segregation:</strong> Machine 2 <code>Facade</code> teilt einen netzwerkweiten R-Port auf zwei lokale P-Ports auf.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">#### Event-Propagation (Asynchroner Pfad)</p>\n<ol class=\"fig-list\">\n<li><strong>Trigger:</strong> <code>AppM1_1</code> emittiert <code>Event1</code>/<code>Event2</code>; <code>AppM1_2</code> emittiert <code>Event3</code> (via <code>ara::com</code> Skeleton-Methoden <code>Send()</code>).</li>\n<li><strong>Lokale Zustellung Machine 1:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Daten passieren den lokalen IPC-Pfad (z. B. Shared Memory / Unix Domain Sockets) zu den R-Ports der providerseitigen <code>Facade</code>.</li>\n<li><code>AppM2_3</code> empfängt parallel <code>Event3</code> und <code>Event4</code> direkt über lokalen IPC.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Netzwerk-Serialisierung:</strong> Die <code>Facade</code> auf Machine 1 triggert die SOME/IP-Serialisierung der gemeinsamen Service-Instanz und sendet SOME/IP-Events via UDP/TCP über das Fahrzeug-Ethernet.</li>\n<li><strong>Empfang & Demultiplexing Machine 2:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Der SOME/IP-Daemon / Netzwerk-Stack von Machine 2 routet das Paket an den R-Port der Consumer-<code>Facade</code>.</li>\n<li>Die <code>Facade</code> trennt die Payload anhand des konfigurierten Mappings:</li>\n<li><code>Event1</code> und <code>Event3</code> werden auf <code>Service 3</code> gemappt und via lokalem IPC an <code>AppM2_1</code> gesendet.</li>\n<li><code>Event2</code> wird auf <code>Service 4</code> gemappt und via lokalem IPC an <code>AppM2_2</code> zugestellt.</li>\n</ul>\n<p class=\"fig-p\">#### Methoden-Aufruf (Synchroner / Asynchroner Request-Response-Pfad)</p>\n<ol class=\"fig-list\">\n<li><code>AppM2_1</code> ruft <code>Method1</code> auf dem Proxy von <code>Service 3</code> auf.</li>\n<li>Der Aufruf wird über lokalen IPC zur <code>Facade</code> (Machine 2) übertragen.</li>\n<li>Die <code>Facade</code> auf Machine 2 kapselt den Methodenaufruf in eine SOME/IP-Request-Message (<code>SOME/IP Service</code>).</li>\n<li>Machine 1 empfängt die Request-Message am P-Port der <code>Facade</code>, leitet sie per IPC an den R-Port und weiter an das Skeleton von <code>AppM1_1</code>.</li>\n<li>Die Antwort (<code>Response</code>) durchläuft denselben Pfad invers zurück zu <code>AppM2_1</code> (Auflösung des <code>ara::core::Future</code>).</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Manifest-Modellierung (<code>ExecutionManifest</code> & <code>ServiceInstanceManifest</code>):</strong></li>\n<li>Werden Service-Schnittstellen nicht 1:1 netzwerkweit exponiert, erfordert AUTOSAR AP entweder ein direktes <code>ServiceInterfaceElementMapping</code> innerhalb des Deployment-Modells oder den im Diagramm gezeigten Architektur-Workaround mittels expliziter Facade-SWCs.</li>\n<li>Das Mapping verlangt konsistente Datentypen (<code>ApplicationDataType</code> / <code>ImplementationDataType</code>) zwischen den Quell-Elementen von <code>Service 1</code>/<code>Service 2</code> und den Ziel-Elementen von <code>Service 3</code>/<code>Service 4</code>.</li>\n<li><strong>Einfluss auf API-Vertrag (<code>ara::com</code>):</strong></li>\n<li>Die Applikationen (<code>AppM1_x</code>, <code>AppM2_x</code>) bleiben strikt vom physischen SOME/IP-Deployment entkoppelt. Sie implementieren bzw. instanziieren Standard-<code>Proxy</code>- und <code>Skeleton</code>-Klassen ihrer jeweiligen ServiceInterfaces (<code>Service 1</code> bis <code>Service 4</code>).</li>\n<li>Die Facade-Komponenten müssen sowohl Skeleton- als auch Proxy-Instanzen halten und den Datentransfer zwischen ihren R- und P-Ports manuell oder teilgeneriert durchschleifen.</li>\n<li><strong>Performance-, Latenz- und Determinismus-Implikationen:</strong></li>\n<li><strong>Doppelter IPC-Hop:</strong> Aufrufe und Events passieren zwei zusätzliche Prozessgrenzen (Applikation $\\rightarrow$ Facade $\\rightarrow$ Netzwerk-Stack $\\rightarrow$ Netzwerk $\\rightarrow$ Netzwerk-Stack $\\rightarrow$ Facade $\\rightarrow$ Applikation).</li>\n<li><strong>Latenzanalyse:</strong> Bei synchronen Methodenaufrufen (<code>Method1</code>) addieren sich Kontextwechsel und Pufferkopien der IPC-Mechanismen auf beiden Knoten zur Netzwerk-Roundtrip-Time (RTT). Timeout-Parameter für <code>ara::core::Future::wait_for()</code> müssen entsprechend dimensioniert werden.</li>\n<li><strong>Bandbreiten-Optimierung:</strong> Das gezielte Ausblenden irrelevanter Elemente (<code>Event4</code>, <code>Method2</code>) verhindert unnötigen SOME/IP-Traffic und entlastet das Ethernet-Bordnetzwerk.</li>\n</ul>"}, {"id": "FIG-f3e630fb85207f93", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> Komponenten- und Deployment-Diagramm für serviceorientierte Architekturen (SOA) gemäß AUTOSAR Adaptive Platform (AP) Modellierungskonventionen.</li>\n<li><strong>Kontext:</strong> AUTOSAR AP Release R21-11, Spezifikation <code>AUTOSAR_TPS_ManifestSpecification</code>, Kapitel zu <em>Service Interface Deployment</em> und <code>ServiceInterfaceElementMapping</code>.</li>\n<li><strong>Technischer Zweck:</strong> Veranschaulichung des Facade-Entwurfsmusters zur Aggregation und Aufteilung (Splitting/Decomposition) von Service-Elementen (<code>Event</code>, <code>Method</code>) zwischen maschinen-lokalen ServiceInterfaces und einer netzwerkweiten SOME/IP-Service-Instanz. Es zeigt das Selektieren von Teilmengen (Subsets) auf Provider-Seite sowie die bedarfsgerechte Rekombination auf Consumer-Seite über Maschinengrenzen hinweg.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Entitäten & Deployment-Knoten</p>\n<ul class=\"fig-list\">\n<li><strong>Machine 1 (Provider-Knoten):</strong></li>\n<li><code>AppM1_1</code> (Adaptive Application): Provider für <code>Service 1</code> über einen Provided Port (<code>P</code>).</li>\n<li><code>AppM1_2</code> (Adaptive Application): Provider für <code>Service 2</code> über einen Provided Port (<code>P</code>).</li>\n<li><code>AppM2_3</code> (Lokale Consumer-Applikation auf Machine 1): Konsumiert <code>Service 2</code> intern über Required Port (<code>R</code>).</li>\n<li><code>Facade</code> (Adaptive Application / Service Broker):</li>\n<li>2× Required Ports (<code>R</code>): Terminierung der lokalen Schnittstellen von <code>AppM1_1</code> und <code>AppM1_2</code>.</li>\n<li>1× Provided Port (<code>P</code>): Aggregierte SOME/IP-Schnittstelle zur Machine 2.</li>\n<li><strong>Machine 2 (Consumer-Knoten):</strong></li>\n<li><code>Facade</code> (Adaptive Application / Service Dispatcher):</li>\n<li>1× Required Port (<code>R</code>): Empfang der SOME/IP-Service-Instanz über das Netzwerk.</li>\n<li>2× Provided Ports (<code>P</code>): Bereitstellung der aufgeteilten Subsets an die lokalen Konsumenten.</li>\n<li><code>AppM2_1</code> (Adaptive Application): Consumer für <code>Service 3</code> über Required Port (<code>R</code>).</li>\n<li><code>AppM2_2</code> (Adaptive Application): Consumer für <code>Service 4</code> über Required Port (<code>R</code>).</li>\n</ul>\n<p class=\"fig-p\">#### Schnittstellen, Element-Granularität & Mapping</p>\n<ul class=\"fig-list\">\n<li><strong><code>Service 1</code> (Machine 1 intern):</strong> Besteht aus <code>{Event1, Event2, Method1}</code>.</li>\n<li><strong><code>Service 2</code> (Machine 1 intern):</strong> Besteht aus <code>{Event3, Event4, Method2}</code>.</li>\n<li><strong><code>SOME/IP Service</code> (Netzwerk-Ebene):</strong> Aggregiert selektiv <code>{Event1, Event2, Event3, Method1}</code>.</li>\n<li><em>Subset-Extraktion Provider-Seite:</em> Vollständige Übernahme von <code>Service 1</code>; selektive Extraktion von <code>Event3</code> aus <code>Service 2</code>. Die Elemente <code>Event4</code> und <code>Method2</code> verbleiben lokal bei <code>AppM2_3</code> und belasten das Netzwerk nicht.</li>\n<li><strong><code>Service 3</code> (Machine 2 intern):</strong> Rekombiniertes Subset bestehend aus <code>{Event1, Event3, Method1}</code> für <code>AppM2_1</code>.</li>\n<li><strong><code>Service 4</code> (Machine 2 intern):</strong> Isoliertes Subset bestehend aus <code>{Event2}</code> für <code>AppM2_2</code>.</li>\n</ul>\n<p class=\"fig-p\">#### Port-Kardinalitäten & Topologie</p>\n<ul class=\"fig-list\">\n<li><strong>1:n-Fächerung:</strong> <code>AppM1_2</code> (Port <code>P</code>) bedient simultan die lokale Instanz <code>AppM2_3</code> (Port <code>R</code>) sowie die <code>Facade</code> (Port <code>R</code>).</li>\n<li><strong>N:1-Aggregation:</strong> Machine 1 <code>Facade</code> bündelt zwei R-Ports auf einen netzwerkweiten P-Port.</li>\n<li><strong>1:N-Segregation:</strong> Machine 2 <code>Facade</code> teilt einen netzwerkweiten R-Port auf zwei lokale P-Ports auf.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">#### Event-Propagation (Asynchroner Pfad)</p>\n<ol class=\"fig-list\">\n<li><strong>Trigger:</strong> <code>AppM1_1</code> emittiert <code>Event1</code>/<code>Event2</code>; <code>AppM1_2</code> emittiert <code>Event3</code> (via <code>ara::com</code> Skeleton-Methoden <code>Send()</code>).</li>\n<li><strong>Lokale Zustellung Machine 1:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Daten passieren den lokalen IPC-Pfad (z. B. Shared Memory / Unix Domain Sockets) zu den R-Ports der providerseitigen <code>Facade</code>.</li>\n<li><code>AppM2_3</code> empfängt parallel <code>Event3</code> und <code>Event4</code> direkt über lokalen IPC.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Netzwerk-Serialisierung:</strong> Die <code>Facade</code> auf Machine 1 triggert die SOME/IP-Serialisierung der gemeinsamen Service-Instanz und sendet SOME/IP-Events via UDP/TCP über das Fahrzeug-Ethernet.</li>\n<li><strong>Empfang & Demultiplexing Machine 2:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Der SOME/IP-Daemon / Netzwerk-Stack von Machine 2 routet das Paket an den R-Port der Consumer-<code>Facade</code>.</li>\n<li>Die <code>Facade</code> trennt die Payload anhand des konfigurierten Mappings:</li>\n<li><code>Event1</code> und <code>Event3</code> werden auf <code>Service 3</code> gemappt und via lokalem IPC an <code>AppM2_1</code> gesendet.</li>\n<li><code>Event2</code> wird auf <code>Service 4</code> gemappt und via lokalem IPC an <code>AppM2_2</code> zugestellt.</li>\n</ul>\n<p class=\"fig-p\">#### Methoden-Aufruf (Synchroner / Asynchroner Request-Response-Pfad)</p>\n<ol class=\"fig-list\">\n<li><code>AppM2_1</code> ruft <code>Method1</code> auf dem Proxy von <code>Service 3</code> auf.</li>\n<li>Der Aufruf wird über lokalen IPC zur <code>Facade</code> (Machine 2) übertragen.</li>\n<li>Die <code>Facade</code> auf Machine 2 kapselt den Methodenaufruf in eine SOME/IP-Request-Message (<code>SOME/IP Service</code>).</li>\n<li>Machine 1 empfängt die Request-Message am P-Port der <code>Facade</code>, leitet sie per IPC an den R-Port und weiter an das Skeleton von <code>AppM1_1</code>.</li>\n<li>Die Antwort (<code>Response</code>) durchläuft denselben Pfad invers zurück zu <code>AppM2_1</code> (Auflösung des <code>ara::core::Future</code>).</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Manifest-Modellierung (<code>ExecutionManifest</code> & <code>ServiceInstanceManifest</code>):</strong></li>\n<li>Werden Service-Schnittstellen nicht 1:1 netzwerkweit exponiert, erfordert AUTOSAR AP entweder ein direktes <code>ServiceInterfaceElementMapping</code> innerhalb des Deployment-Modells oder den im Diagramm gezeigten Architektur-Workaround mittels expliziter Facade-SWCs.</li>\n<li>Das Mapping verlangt konsistente Datentypen (<code>ApplicationDataType</code> / <code>ImplementationDataType</code>) zwischen den Quell-Elementen von <code>Service 1</code>/<code>Service 2</code> und den Ziel-Elementen von <code>Service 3</code>/<code>Service 4</code>.</li>\n<li><strong>Einfluss auf API-Vertrag (<code>ara::com</code>):</strong></li>\n<li>Die Applikationen (<code>AppM1_x</code>, <code>AppM2_x</code>) bleiben strikt vom physischen SOME/IP-Deployment entkoppelt. Sie implementieren bzw. instanziieren Standard-<code>Proxy</code>- und <code>Skeleton</code>-Klassen ihrer jeweiligen ServiceInterfaces (<code>Service 1</code> bis <code>Service 4</code>).</li>\n<li>Die Facade-Komponenten müssen sowohl Skeleton- als auch Proxy-Instanzen halten und den Datentransfer zwischen ihren R- und P-Ports manuell oder teilgeneriert durchschleifen.</li>\n<li><strong>Performance-, Latenz- und Determinismus-Implikationen:</strong></li>\n<li><strong>Doppelter IPC-Hop:</strong> Aufrufe und Events passieren zwei zusätzliche Prozessgrenzen (Applikation $\\rightarrow$ Facade $\\rightarrow$ Netzwerk-Stack $\\rightarrow$ Netzwerk $\\rightarrow$ Netzwerk-Stack $\\rightarrow$ Facade $\\rightarrow$ Applikation).</li>\n<li><strong>Latenzanalyse:</strong> Bei synchronen Methodenaufrufen (<code>Method1</code>) addieren sich Kontextwechsel und Pufferkopien der IPC-Mechanismen auf beiden Knoten zur Netzwerk-Roundtrip-Time (RTT). Timeout-Parameter für <code>ara::core::Future::wait_for()</code> müssen entsprechend dimensioniert werden.</li>\n<li><strong>Bandbreiten-Optimierung:</strong> Das gezielte Ausblenden irrelevanter Elemente (<code>Event4</code>, <code>Method2</code>) verhindert unnötigen SOME/IP-Traffic und entlastet das Ethernet-Bordnetzwerk.</li>\n</ul>"}], "trans": [{"from": "FIG-0acd62c6383ca86f", "to": "FIG-f4c7afdd5f68e0f8", "fr": "R21-11", "tr": "R22-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-f4c7afdd5f68e0f8", "to": "FIG-b8956c717dfea76b", "fr": "R22-11", "tr": "R23-11", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li>Service 3 (Callout-Position): Die Callout-Box für <code>Service 3 with Event1, Event3, Method1</code> wurde von links neben <code>AppM2_1</code> nach oben oberhalb der Komponente verschoben.</li>\n<li>AppM2_1 (Geometrie): Die Box <code>AppM2_1</code> wurde in der Höhe verkleinert (flacheres Rechteck).</li>\n<li>Verbindung Facade zu AppM2_1: Die Verbindungslinie vom oberen P-Port der <code>Facade</code> zum R-Port von <code>AppM2_1</code> verläuft nun horizontal geradlinig.</li>\n<li>Strichstärken: Die Konturlinien der Maschinenrahmen (<code>Machine 1</code>, <code>Machine 2</code>), Komponentenboxen (<code>AppM1_1</code>, <code>AppM1_2</code>, <code>AppM2_3</code>, <code>AppM2_1</code>, <code>AppM2_2</code>, <code>Facade</code>) sowie Callouts sind mit dickerer Linienstärke (fett) gezeichnet.</li>\n</ul>"}, {"from": "FIG-b8956c717dfea76b", "to": "FIG-b54dc1f1dcd5453e", "fr": "R23-11", "tr": "R24-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-b54dc1f1dcd5453e", "to": "FIG-f3e630fb85207f93", "fr": "R24-11", "tr": "R25-11", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li>Service-Beschriftungen (Notationsstil): Die Sprechblasen-/Callout-Boxen für <code>Service 1</code>, <code>Service 2</code>, <code>Service 3</code> und <code>Service 4</code> wurden durch freistehenden Text mit gestrichelten Hinweislinien zu den Ports ersetzt.</li>\n<li>Facade Machine 1: Die beiden R-Ports der providerseitigen <code>Facade</code> sind nun zusätzlich über eine vertikale Linie direkt miteinander verbunden.</li>\n<li>Facade Machine 2: Die beiden P-Ports der consumerseitigen <code>Facade</code> sind nun zusätzlich über eine vertikale Linie direkt miteinander verbunden.</li>\n<li>Maschinenbeschriftung: Die Bezeichner <code>Machine 1</code> und <code>Machine 2</code> sind fett dargestellt und oben links im jeweiligen Rahmen platziert.</li>\n<li>Port-Darstellung: Die Port-Kästchen (<code>P</code>, <code>R</code>) sind zentriert auf die Randlinien der Komponenten aufgesetzt.</li>\n</ul>"}]};
